<template>
  <section id="choose-how-you-want-to-explore" class="ai-path" aria-labelledby="ai-path-title">
    <header class="ai-path-header">
      <span>One site, three ways to explore</span>
      <h2 id="ai-path-title">Choose how you want to explore</h2>
    </header>

    <div class="ai-path-tabs" role="tablist" aria-label="Site AI capability">
      <button
        v-for="path in paths"
        :id="`ai-path-tab-${path.id}`"
        :key="path.id"
        type="button"
        role="tab"
        :aria-selected="(active === path.id).toString()"
        :aria-controls="`ai-path-panel-${path.id}`"
        :class="{ active: active === path.id }"
        @click="active = path.id"
      >
        <span>{{ path.verb }}</span>
        <strong><AiViewTerm v-if="path.id === 'view'" /><AiAskTerm v-else-if="path.id === 'ask'" /><template v-else>{{ path.label }}</template></strong>
      </button>
    </div>

    <transition name="ai-path-panel" mode="out-in">
      <article
        :id="`ai-path-panel-${current.id}`"
        :key="current.id"
        class="ai-path-panel"
        role="tabpanel"
        :aria-labelledby="`ai-path-tab-${current.id}`"
      >
        <div class="ai-path-copy">
          <span>{{ current.kicker }}</span>
          <h3 v-if="current.id === 'ask'"><AiAskTerm /> a question and get an answer you can trace</h3>
          <h3 v-else>{{ current.title }}</h3>
          <p v-if="current.id === 'ask'"><AiAskTerm /> finds the relevant passages, writes a direct answer from them, and cites the original pages so you can check the source.</p>
          <p v-else>{{ current.summary }}</p>
          <button type="button" @click="runCurrent">
            <span v-if="current.id === 'view'">Compose a <AiViewTerm /></span>
            <span v-else-if="current.id === 'ask'"><AiAskTerm /> the site</span>
            <span v-else>{{ current.action }}</span>
            <ArrowUpRightIcon />
          </button>
        </div>

        <ol class="ai-path-steps">
          <li v-for="(step, index) in current.steps" :key="step.title">
            <span>{{ String(index + 1).padStart(2, '0') }}</span>
            <div>
              <strong>{{ step.title }}</strong>
              <p>{{ step.body }}</p>
            </div>
          </li>
        </ol>
      </article>
    </transition>
  </section>
</template>

<script>
import AiViewTerm from '../ui/AiViewTerm.vue';
import AiAskTerm from '../ui/AiAskTerm.vue';
import ArrowUpRightIcon from '../ui/ArrowUpRightIcon.vue';

export default {
  name: 'SiteAiPathExplorer',
  components: { AiAskTerm, AiViewTerm, ArrowUpRightIcon },
  data() {
    return {
      active: 'search',
      paths: [
        {
          id: 'search',
          verb: 'Find',
          label: 'Search',
          kicker: 'Across the whole site',
          title: 'Search once and land on the right passage',
          summary: 'Search moves across every page, shows the relevant passage, highlights the match, and opens the original material at its precise location. It compares both shared wording and shared meaning.',
          action: 'Try Search',
          event: 'open-search',
          steps: [
            { title: 'Represent meaning', body: 'Turn every passage and the question into coordinates that can be compared by meaning.' },
            { title: 'Compare', body: 'Look for both matching words and related meaning across the whole site.' },
            { title: 'Combine', body: 'Bring both result lists together while preserving strong name and phrase matches.' },
            { title: 'Open', body: 'Send the reader back to the original material and its precise location.' },
          ],
        },
        {
          id: 'ask',
          verb: 'Answer',
          label: 'Ask',
          kicker: 'An answer with citations',
          title: 'Ask a question and get an answer you can trace',
          summary: 'Ask finds the relevant passages, writes a direct answer from them, and cites the original pages so you can check the source.',
          action: 'Ask the site',
          event: 'open-ask',
          steps: [
            { title: 'Find evidence', body: 'Collect the site material most relevant to the visitor’s question.' },
            { title: 'Set the scope', body: 'Give the answer model a clear set of passages it can use.' },
            { title: 'Write', body: 'Turn those passages into a direct answer.' },
            { title: 'Cite', body: 'Connect the response back to the original pages it used.' },
          ],
        },
        {
          id: 'view',
          verb: 'Compose',
          label: 'View',
          kicker: 'A new reading path',
          title: 'Turn an angle into a page built from original material',
          summary: 'The composer gathers material from across the site, connects it around one angle, and places original components beside the narrative. The finished page is saved with its creation date and sources.',
          action: 'Compose',
          event: 'compose-view',
          steps: [
            { title: 'Gather', body: 'Find a broader set of material that can support the chosen angle.' },
            { title: 'Plan', body: 'Select the useful sources and arrange them into a reading sequence.' },
            { title: 'Compose', body: 'Write the narrative and place original site components where they add evidence.' },
            { title: 'Save', body: 'Keep the finished View, its creation date, and its sources in a shareable link.' },
          ],
        },
      ],
    };
  },
  computed: {
    current() {
      return this.paths.find((path) => path.id === this.active) || this.paths[0];
    },
  },
  methods: {
    runCurrent() {
      if (this.current.id === 'search') {
        window.dispatchEvent(new CustomEvent('open-site-search'));
        return;
      }
      if (this.current.id === 'ask') {
        window.dispatchEvent(new CustomEvent('open-site-ask'));
        return;
      }
      window.dispatchEvent(new CustomEvent('open-site-view'));
    },
  },
};
</script>

