// View selection reads the complete catalog. These descriptions describe source
// content, never rules about which question should activate a source.
export function describeViewSource(source) {
  const text = String(source?.description || source?.body || source?.parts?.join(' ') || source?.title || '')
    .replace(/\s+/g, ' ').trim();
  if (text.length <= 420) return text;
  const prefix = text.slice(0, 421);
  const sentenceEnd = Math.max(prefix.lastIndexOf('. '), prefix.lastIndexOf('! '), prefix.lastIndexOf('? '), prefix.lastIndexOf('。'));
  if (sentenceEnd >= 200) return prefix.slice(0, sentenceEnd + 1);
  return `${prefix.slice(0, 417).replace(/\s+\S*$/, '')}…`;
}

export function createViewCatalog(index) {
  const sources = (index?.sources || []).filter((source) => !source.search_only).map((source) => ({
    source_id: source.source_id, id: source.id, route: source.route, page: source.page,
    title: source.title, anchor: source.anchor || '',
    description: describeViewSource(source), body: source.body, parts: source.parts || [],
    view_kind: source.view_kind, presentations: source.presentations || ['cite'],
    component_description: source.component_description || '',
    media: source.media || [], entity: source.entity || null,
  }));
  const interactions = (index?.rich_blocks || []).map((block) => {
    const parent = sources.find((source) => source.route === block.route && !source.anchor && source.view_kind === 'prose')
      || sources.find((source) => source.entity?.richBlock === block.id);
    return {
      source_id: block.id, route: block.route, page: block.title, title: block.title,
      anchor: block.anchor || '', description: describeViewSource(block),
      body: block.description, parts: [block.description, (block.topics || []).join(', ')].filter(Boolean),
      component_description: block.componentDescription || block.description,
      view_kind: block.kind === 'interactive' ? 'interactive' : 'embed',
      presentations: [block.allowedPresentation], media: block.media || [],
      entity: block.entity || null, rich: true,
      companion_for: parent?.source_id || '',
    };
  });
  return [...new Map([...sources, ...interactions].map((source) => [source.source_id, source])).values()];
}

function periodFromBody(source) {
  const text = String(source?.body || source?.parts?.[0] || '').trim();
  const match = text.match(/^([A-Z][a-z]+\s+\d{4}\s+-\s+(?:[A-Z][a-z]+\s+\d{4}|Present))\b/);
  return match ? match[1] : '';
}

export function viewTemporalMetadata(source) {
  const period = String(source?.entity?.period || periodFromBody(source)).trim();
  const status = String(source?.entity?.status || '').trim();
  if (!period) return status ? { status } : {};
  return {
    period,
    ...(status ? { status } : {}),
  };
}

export function viewSelectionDescriptor(source) {
  return {
    source_id: source.source_id,
    title: source.title,
    page: source.page,
    kind: source.view_kind || 'prose',
    description: describeViewSource(source),
    ...viewTemporalMetadata(source),
    ...(source.component_description ? { component: source.component_description } : {}),
    ...(source.companion_for ? { companion_for: source.companion_for } : {}),
  };
}
