<template>
  <div class="summary-audio" :class="{ 'is-playing': playing, 'is-loading': loading }">
    <div class="summary-audio-row">
      <button type="button" class="summary-audio-toggle" :disabled="!audioRequest" :aria-label="buttonLabel" @pointerup="releasePointerFocus" @pointercancel="releasePointerFocus" @click="toggle">
        <span class="summary-audio-icon" aria-hidden="true">
          <span v-if="loading" class="summary-audio-spinner"></span>
          <svg v-else-if="playing" viewBox="0 0 20 20"><path d="M6 5v10M14 5v10" fill="none" stroke="currentColor" stroke-width="3" /></svg>
          <svg v-else viewBox="0 0 20 20"><path d="M7 4.5 16 10l-9 5.5Z" fill="currentColor" /></svg>
        </span>
        <span class="summary-audio-copy">
          <span class="summary-audio-label">{{ playbackLabel }}</span>
          <span class="summary-audio-byline">Henry’s AI voice</span>
        </span>
      </button>
      <span class="summary-audio-time" :class="{ 'is-pending': duration <= 0 }">
        <template v-if="duration > 0">{{ clock(currentTime) }} / {{ clock(duration) }}</template>
        <template v-else>Summary audio</template>
      </span>
    </div>
    <div class="summary-audio-track">
      <input v-if="duration > 0" class="summary-audio-seek" type="range" min="0" :max="duration" step="0.1" :value="currentTime" :style="{ '--audio-progress': `${progressPercent}%` }" aria-label="Summary playback position" :aria-valuetext="`${clock(currentTime)} of ${clock(duration)}`" @input="seek">
      <span v-else class="summary-audio-rail" aria-hidden="true"><span :class="{ 'is-active': loading }"></span></span>
    </div>
    <p v-if="error" class="summary-audio-error" role="status">{{ error }}</p>
    <p v-else-if="!audioRequest" class="summary-audio-error">Audio will be available once this View is saved.</p>
    <span class="summary-audio-status" role="status">{{ loading ? loadingLabel : '' }}</span>
    <audio ref="audio" preload="none" :src="audioUrl || undefined" @loadedmetadata="updateTime" @durationchange="updateTime" @timeupdate="updateTime" @play="playing = true" @pause="playing = false" @ended="playing = false" @error="playbackError" />
  </div>
</template>

<script>
import { askEndpoints } from '../../utils/askSite';
import { summaryAudioRequest } from '../../utils/viewAudio';

export default {
  name: 'ViewSummaryAudio',
  props: { shareId: { type: String, default: '' }, audioSrc: { type: String, default: '' } },
  data: () => ({ audioUrl: '', loading: false, playing: false, currentTime: 0, duration: 0, error: '' }),
  computed: {
    audioRequest() { return summaryAudioRequest(askEndpoints()[0], this.shareId, this.audioSrc); },
    loadingLabel() { return this.audioRequest?.method === 'GET' ? 'Loading your audio…' : 'Preparing your audio…'; },
    playbackLabel() {
      if (this.loading) return this.loadingLabel;
      if (this.playing) return 'Playing summary';
      if (this.currentTime > 0) return 'Continue summary';
      return 'Listen to summary';
    },
    progressPercent() { return this.duration > 0 ? Math.min(100, Math.max(0, (this.currentTime / this.duration) * 100)) : 0; },
    buttonLabel() {
      if (this.loading) return 'Cancel loading summary audio';
      return `${this.playing ? 'Pause' : 'Play'} summary in Henry’s AI voice`;
    },
  },
  mounted() {
    this._onOtherAudio = (event) => { if (event.detail !== this) this.$refs.audio?.pause(); };
    window.addEventListener('view-summary-play', this._onOtherAudio);
    this._onMediaPlay = (event) => { if (event.target !== this.$refs.audio) this.$refs.audio?.pause(); };
    document.addEventListener('play', this._onMediaPlay, true);
  },
  beforeUnmount() {
    window.removeEventListener('view-summary-play', this._onOtherAudio);
    document.removeEventListener('play', this._onMediaPlay, true);
    this.reset();
  },
  watch: { audioSrc() { this.reset(); }, shareId() { if (!this.audioSrc) this.reset(); } },
  methods: {
    reset() {
      this._request?.abort();
      this._request = null;
      this.$refs.audio?.pause();
      if (this.audioUrl) URL.revokeObjectURL(this.audioUrl);
      this.audioUrl = '';
      this.loading = false;
      this.playing = false;
      this.currentTime = 0;
      this.duration = 0;
      this.error = '';
    },
    async toggle() {
      if (this.loading) { this.reset(); return; }
      if (this.playing) { this.$refs.audio.pause(); return; }
      if (!this.audioRequest) return;
      this.error = '';
      if (!this.audioUrl) {
        const controller = new AbortController();
        this._request = controller;
        this.loading = true;
        const timeout = setTimeout(() => controller.abort(), 70000);
        try {
          const { url, method } = this.audioRequest;
          let response;
          do {
            response = await fetch(url, { method, signal: controller.signal });
            if (response.status !== 202) break;
            await response.body?.cancel();
            const seconds = Math.min(5, Math.max(1, Number(response.headers.get('Retry-After')) || 2));
            await new Promise((resolve, reject) => {
              const timer = setTimeout(resolve, seconds * 1000);
              controller.signal.addEventListener('abort', () => {
                clearTimeout(timer);
                reject(controller.signal.reason);
              }, { once: true });
            });
          } while (!controller.signal.aborted);
          if (!response.ok || !response.headers.get('content-type')?.startsWith('audio/')) throw new Error('unavailable');
          const blob = await response.blob();
          if (this._request !== controller) return;
          this.audioUrl = URL.createObjectURL(blob);
        } catch {
          if (this._request === controller) this.error = 'Audio is temporarily unavailable. Tap play to try again.';
          return;
        } finally {
          clearTimeout(timeout);
          if (this._request === controller) { this._request = null; this.loading = false; }
        }
      }
      await this.$nextTick();
      const audio = this.$refs.audio;
      if (!audio || !this.audioUrl) return;
      if (audio.ended) audio.currentTime = 0;
      window.dispatchEvent(new CustomEvent('view-summary-play', { detail: this }));
      try { await audio.play(); } catch { this.error = 'Your audio is ready. Tap play to listen.'; }
    },
    updateTime() {
      const audio = this.$refs.audio;
      this.duration = Number.isFinite(audio?.duration) ? audio.duration : 0;
      this.currentTime = audio?.currentTime || 0;
    },
    seek(event) { this.$refs.audio.currentTime = Number(event.target.value); this.updateTime(); },
    releasePointerFocus(event) { event.currentTarget?.blur(); },
    clock(seconds) { const n = Math.floor(seconds || 0); return `${Math.floor(n / 60)}:${String(n % 60).padStart(2, '0')}`; },
    playbackError() {
      if (this.audioUrl) { this.reset(); this.error = 'Audio could not be played. Tap play to try again.'; }
    },
  },
};
</script>

